mapper.select:
select card_id, lead_id, card_status, cast(basics as text) as basics, cast(ai_content as text) as ai_content, input_digest, ai_call_id,
       ai_status, error_msg, trigger_type, generated_time, create_by, create_time, update_by, update_time
from abr_lead_card where lead_id = #{leadId}
